// IEC string operations: FIND, MID, LEFT, RIGHT, LEN, STRING(n)
VAR
    s : STRING(80);
    pos, length : INT;
    sub : STRING(20);
END_VAR
length := LEN(s);
pos := FIND(s, '.'); // 1-based index; returns 0 if not found
IF pos > 1 THEN
    sub := LEFT(s, pos - 1); // extracts prefix
END_IF;

// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!
VAR
    timer : TON;
    runTimer : BOOL;
END_VAR
// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):
runTimer := (state = 1) AND NOT resetCmd;
timer(IN := runTimer, PT := T#2s);
IF timer.Q THEN
    // Timer expired; timer.ET holds elapsed time
END_IF;
